// Brief form answers -> the run: id, brief fields, voice and b-roll switches, link or upload.
const item = $input.first();
const f = item.json;
const run_id = String($execution.id);
if (!/^[A-Za-z0-9_-]{1,64}$/.test(run_id)) throw new Error('execution id ' + run_id + ' is not a valid run id');
const txt = (k) => String(f[k] == null ? '' : f[k]).trim();
const brief = {
  brand: txt('Brand'), product: txt('Product'), audience: txt('Audience'), offer: txt('Offer'),
  key_messages: [txt('Key message 1'), txt('Key message 2'), txt('Key message 3')].filter(Boolean),
  disclaimer: txt('Required disclaimer'), look: txt('Look'), beats: String(f['Beats'] == null ? '' : f['Beats']),
};
for (const k of ['brand', 'product', 'offer']) if (!brief[k]) throw new Error('the brief needs a ' + k);
if (brief.key_messages.length < 3) throw new Error('the brief needs 3 key messages');
if (!brief.beats.trim()) throw new Error('the brief needs beats');
const link = txt('Source clip link');
if (link && !/^https:\/\/\S+$/i.test(link)) throw new Error('Source clip link must be an https:// address (no spaces)');
const bin = item.binary || {};
const key = Object.keys(bin)[0];
if (!link && !key) throw new Error('give a source clip: upload a file or paste an https link');
// Voice and B-roll are separate switches, both defaulting to the stand-in (a missing field is the stand-in, the safe default).
// The old single "Dry run" checkbox is still honoured when a script posts it: [] (unticked) meant live b-roll and the real voice.
const legacy = f['Dry run'];
const voice_mode = (Array.isArray(legacy) && legacy.length === 0) || /^real/i.test(txt('Voice')) ? 'real' : 'stand-in';
const broll_mode = (Array.isArray(legacy) && legacy.length === 0) || /^live/i.test(txt('B-roll')) ? 'live' : 'stand-in';
const dry_run = broll_mode !== 'live';        // the b-roll switch of the first half: stand-in clips, no pods
const landing = txt('Landing URL');
if (landing && !/^https:\/\/\S+$/i.test(landing)) throw new Error('Landing URL must be an https:// address (no spaces)');
brief.landing_url = landing; brief.cta = txt('Call to action') || 'Learn More';
return [{ json: { run_id, brief, dry_run, voice_mode, broll_mode, link, source_origin: link ? 'link' : 'upload' }, binary: link ? {} : { data: bin[key] } }];

// /run answered with just the folder name: put the run and the uploaded file back.
const prev = $('Run: ids and brief').first();
return [{ json: prev.json, binary: prev.binary }];

// The end card shows the rulebook's disclaimer, so the brief's must be that text (case, spacing and punctuation ignored).
const prev = $('Run: restore').first();
const S = prev.json;
const rb = $input.first().json;
const norm = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
if (norm(S.brief.disclaimer) !== norm(rb.disclaimer)) throw new Error("the brief's disclaimer differs from the approved one in the rulebook");
return [{ json: { ...S, rulebook: rb, disclaimer: rb.disclaimer }, binary: prev.binary }];

// The link's download is capped (single constant): refuse before anything is written into the run.
const MAX_MB = 400;
const b = $input.first().binary && $input.first().binary.data;
if (!b) throw new Error('the link gave no file');
const bytes = Number(b.bytes || 0);
if (bytes > MAX_MB * 1024 * 1024) throw new Error('the linked file is ' + Math.round(bytes / 1048576) + ' MB; the limit is ' + MAX_MB + ' MB');
return $input.all();

// One beat per line:  NAME START-END ROLE [POSITION ...]   (blank lines and # comments are ignored)
//   NAME      S1 .. S6, each once
//   START-END seconds in the source clip, e.g. 0.5-6.0
//   ROLE      a free label: opener-H1, tension, routine, opener-H2, calm, close
//   POSITION  where the 9:16 / 1:1 crop window sits, any of these (default: centre):
//             left | centre | right | auto | a number 0..1 (window centre as a share of the width)   -> the service's `face`
//             x9=0.21 and/or x1=0.30, comma-joined or separate (9:16 and 1:1 centres)              -> the service's `x`
const S = $input.first().json;
const FACES = { left: 'left', centre: 'centre', center: 'centre', right: 'right', auto: 'auto' };
const NAMES = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6'];
const text = S.brief.beats.replace(/(\d)\s*[-–—]\s*(\d)/g, '$1-$2');
const lines = text.split(/\r?\n/).map((l) => l.replace(/#.*$/, '').trim()).filter(Boolean);
const beats = [];
const errs = [];
lines.forEach((line, i) => {
  const where = 'beats line ' + (i + 1) + ' ("' + line + '")';
  const t = line.split(/\s+/);
  if (t.length < 3) { errs.push(where + ': needs NAME START-END ROLE'); return; }
  const name = t[0].toUpperCase();
  if (!NAMES.includes(name)) errs.push(where + ': the name must be one of ' + NAMES.join(', '));
  const m = t[1].match(/^(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)$/);
  if (!m) { errs.push(where + ': the times must look like 0.5-6.0'); return; }
  const start = Number(m[1]); const end = Number(m[2]);
  if (!(end > start)) errs.push(where + ': the end must be after the start');
  const beat = { name, start, end, role: t[2] };
  let face = 'centre'; const x = {};
  for (const tok of t.slice(3)) {
    const lower = tok.toLowerCase();
    if (FACES[lower]) { face = FACES[lower]; continue; }
    if (/^(0(\.\d+)?|1(\.0+)?|\.\d+)$/.test(lower)) { face = Number(lower); continue; }
    let ok = true;
    for (const part of lower.split(',').filter(Boolean)) {
      const p = part.match(/^(x9|x1|9x16|1x1)=(0(?:\.\d+)?|1(?:\.0+)?|\.\d+)$/);
      if (!p) { ok = false; break; }
      x[p[1] === 'x9' || p[1] === '9x16' ? '9X16' : '1X1'] = Number(p[2]);
    }
    if (!ok) errs.push(where + ': "' + tok + '" is not a position (left, centre, right, auto, 0..1, x9=0.2, x1=0.4)');
  }
  beat.face = face;
  if (Object.keys(x).length) beat.x = x;
  beats.push(beat);
});
const seen = beats.map((b) => b.name);
for (const n of NAMES) if (seen.filter((s) => s === n).length !== 1) errs.push('beat ' + n + ' must appear exactly once (all of S1 to S6 are needed)');
if (errs.length) throw new Error('beats: ' + errs.join('; '));
beats.sort((a, b) => a.name.localeCompare(b.name));
const body = { run_id: S.run_id, source: S.source, beats, formats: ['9X16', '1X1'] };
return [{ json: { ...S, beats, body } }];

const S = $('Beats: parse').first().json;
const r = $input.first().json;
const flags = [];
for (const [beat, fm] of Object.entries(r.beats || {})) for (const [fmt, s] of Object.entries(fm)) {
  if (s.split) flags.push(beat + ' ' + fmt + ' split');
  if (s.review) flags.push(beat + ' ' + fmt + ' review');
}
const { body, ...rest } = S;
return [{ json: { ...rest, reframe: { beats: r.beats, sheet: r.sheet, flags } } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// Script prompt: the brief + the rulebook -> 2 hooks, a voice-over line per length, 3 b-roll shots per hook.
const S = $('Reframe: keep').first().json;
const rb = S.rulebook;
const b = S.brief;
const beatList = S.beats.map((x) => x.name + ' (' + x.role + ')').join(', ');
const system = [
  'You write voice-over scripts and b-roll shot lists for short paid-social video ads for a fictional sleep telehealth brand.',
  'Return only the JSON object asked for. No commentary.',
].join(' ');
const user = [
  'BRIEF',
  'Brand: ' + b.brand,
  'Product: ' + b.product,
  'Audience: ' + b.audience,
  'Offer: ' + b.offer,
  'Key messages: ' + b.key_messages.map((m, i) => (i + 1) + '. ' + m).join(' '),
  '',
  'RULEBOOK',
  'Tone: ' + rb.tone,
  'Approved claims (describe the service only in these terms): ' + rb.claims.map((c) => '"' + c + '"').join('; '),
  '',
  'THE FOOTAGE',
  'One source clip of ' + S.beats.length + ' beats: ' + beatList + '. Hook H1 opens on S1, hook H2 opens on S4. The lines are spoken over the picture.',
  '',
  'TASK',
  'Write 2 hooks, H1 and H2, each a different angle on the brief. For each hook write one voice-over line per length:',
  '"6" (a 6 second ad, at most 9 words), "15" (at most 28 words), "30" (at most 60 words). Longer lines include the shorter idea; speak plainly, one spoken sentence at a time.',
  'Never write a first-person or testimonial-style line ("I finally sleep through the night"): the voice is the brand talking about the service. Never promise an outcome.',
  'For each hook choose 3 b-roll shots (the cutaways in slots A, B, C) from the approved list only, copying the text exactly:',
  rb.shots.map((s) => '- ' + s).join('\n'),
].join('\n');
const schema = {
  type: 'object', additionalProperties: false, required: ['hooks'],
  properties: { hooks: { type: 'array', minItems: 2, maxItems: 2, items: {
    type: 'object', additionalProperties: false, required: ['id', 'lines', 'broll'],
    properties: {
      id: { type: 'string', enum: ['H1', 'H2'] },
      lines: { type: 'object', additionalProperties: false, required: ['6', '15', '30'], properties: { '6': { type: 'string' }, '15': { type: 'string' }, '30': { type: 'string' } } },
      broll: { type: 'array', minItems: 3, maxItems: 3, items: { type: 'string', enum: rb.shots } },
    } } } },
};
const body = { model: 'google/gemini-4-argon', messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'ad_scripts', strict: true, schema } } };
const { body: _b, ...rest } = S;
return [{ json: { ...rest, llm_usd: S.llm_usd || 0, body } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// Shape check of the model's JSON; b-roll shots must be rulebook shots.
const S = $('Scripts: prompt').first().json;
const r = $input.first().json;
const MAXW = { '6': 12, '15': 34, '30': 70 };
let out;
try { out = parseJson(llmText(r)); } catch (e) { throw new Error('scripts: the model did not return JSON (' + e.message + ')'); }
if (!out || !Array.isArray(out.hooks) || out.hooks.length !== 2) throw new Error('scripts: expected {"hooks": [H1, H2]}');
const shots = S.rulebook.shots;
const norm = (s) => String(s).trim().toLowerCase();
const notes = [];
const hooks = out.hooks.map((h, i) => {
  const id = 'H' + (i + 1);
  if (!h || h.id !== id) throw new Error('scripts: hook ' + (i + 1) + ' must have id ' + id);
  const lines = {};
  for (const len of ['6', '15', '30']) {
    const t = h.lines && typeof h.lines[len] === 'string' ? h.lines[len].trim() : '';
    if (!t) throw new Error('scripts: ' + id + ' has no ' + len + ' s line');
    const words = t.split(/\s+/).length;
    if (words > MAXW[len]) notes.push(id + ' ' + len + ' s line has ' + words + ' words (more than ' + MAXW[len] + '): it may not fit before the end card');
    lines[len] = t;
  }
  if (!Array.isArray(h.broll) || h.broll.length !== 3) throw new Error('scripts: ' + id + ' needs 3 b-roll shots');
  const broll = h.broll.map((s) => {
    const hit = shots.find((x) => norm(x) === norm(s));
    if (!hit) throw new Error('scripts: ' + id + ' b-roll shot is not in the rulebook: ' + JSON.stringify(s));
    return hit;
  });
  const used = new Set();
  const repaired = broll.map((shot, k) => {
    if (!used.has(shot)) { used.add(shot); return shot; }
    const fresh = shots.find((x) => !used.has(x) && !broll.includes(x)) || shots.find((x) => !used.has(x));
    notes.push(id + ' b-roll ' + 'ABC'[k] + ' repeated a shot of the same hook; replaced by "' + fresh + '"');
    used.add(fresh);
    return fresh;
  });
  return { id, lines, broll: repaired };
});
const { body, ...rest } = S;
return [{ json: { ...rest, hooks, scripts_raw: hooks, script_notes: notes, llm_usd: (S.llm_usd || 0) + cost(r) } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// Every line and every b-roll shot gets an id (H1:6, H1:15, H1:30, H1:A, H1:B, H1:C ...) and goes to the hard word list.
const S = $input.first().json;
const items = [];
for (const h of S.hooks) {
  for (const len of ['6', '15', '30']) items.push({ id: h.id + ':' + len, kind: 'line', hook: h.id, key: len, text: h.lines[len] });
  ['A', 'B', 'C'].forEach((l, i) => items.push({ id: h.id + ':' + l, kind: 'shot', hook: h.id, key: l, text: h.broll[i] }));
}
return [{ json: { ...S, comp_items: items, body: { texts: items.map((i) => i.text) } } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// Second pass: a model judges each voice-over line against the rulebook; the hard word list's hits are told to it. B-roll shots are only linted.
const S = $('Compliance: collect').first().json;
const hits = $input.first().json.hits;
const rb = S.rulebook;
const items = S.comp_items.map((it, i) => ({ ...it, hits: hits[i] || [] }));
const judged = items.filter((it) => it.kind === 'line');   // b-roll shots are pre-approved: only the word list checks them
const system = 'You are the compliance reviewer for ads of a fictional sleep telehealth service in Australia. Prescription medicines may not be advertised to the public, and indirect pointers to a medicine count. Return only the JSON asked for.';
const user = [
  'RULES',
  'Tone: ' + rb.tone,
  'Allowed ways to describe the service (approved claims): ' + rb.claims.map((c) => '"' + c + '"').join('; '),
  'No testimonial-style or first-person lines. No outcome, result or cure, no promise of better sleep as a result, no medical-treatment pointers, no prices, offers or urgency.',
  'The lines are spoken over pictures that must not suggest: ' + rb.banned_media.join('; ') + '.',
  '',
  'CHECK each item below. ok is true only when it follows every rule. When ok is false, give "rewrite": a compliant replacement with the same job and about the same length, using only the approved claims and a plain, calm voice. When ok is true, rewrite is an empty string.',
  'An item marked HARD WORD LIST HIT contains a banned word and is not ok; its rewrite must not contain that word or any form of it.',
  '',
  'ITEMS',
  judged.map((it) => it.id + ' [voice-over line]' + (it.hits.length ? ' HARD WORD LIST HIT: ' + it.hits.join(', ') : '') + ': ' + it.text).join('\n'),
].join('\n');
const props = {};
for (const it of judged) props[it.id] = { type: 'object', additionalProperties: false, required: ['ok', 'rewrite'], properties: { ok: { type: 'boolean' }, rewrite: { type: 'string' } } };
const schema = { type: 'object', additionalProperties: false, required: judged.map((i) => i.id), properties: props };
const body = { model: 'google/gemini-4-argon', messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'compliance', strict: true, schema } } };
return [{ json: { ...S, comp_items: items, body } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// Rewrite once: a line that failed gets the judge's rewrite (linted again next); a failing shot is dropped.
const S = $('Compliance: judge prompt').first().json;
const r = $input.first().json;
let judge;
try { judge = parseJson(llmText(r)); } catch (e) { throw new Error('compliance: the judge did not return JSON (' + e.message + ')'); }
const items = S.comp_items.map((it) => {
  const j = it.kind === 'line' ? (judge[it.id] || { ok: false, rewrite: '' }) : { ok: true, rewrite: '' };   // shots: word list only
  const failed = it.hits.length > 0 || j.ok !== true;
  const why = [];
  if (it.hits.length) why.push('hard word list: ' + it.hits.join(', '));
  if (j.ok !== true) why.push('judge: not ok');
  if (!failed) return { ...it, status: 'ok', final: it.text, why };
  if (it.kind === 'shot') return { ...it, status: 'dropped', final: null, why: why.concat('b-roll shots are not rewritten') };
  const rw = typeof j.rewrite === 'string' ? j.rewrite.trim() : '';
  if (!rw || rw === it.text) return { ...it, status: 'dropped', final: null, why: why.concat('no usable rewrite') };
  return { ...it, status: 'rewritten', rewrite: rw, final: rw, why };
});
const rewritten = items.filter((i) => i.status === 'rewritten');
const { body, ...rest } = S;
return [{ json: { ...rest, comp_items: items, llm_usd: (S.llm_usd || 0) + cost(r), body: { texts: rewritten.map((i) => i.rewrite) } } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

// A rewrite that still hits the word list is dropped; hooks left without lines are dropped; the report notes all of it.
const S = $('Compliance: apply 1').first().json;
const hits = $input.first().json.hits || [];
let k = 0;
const items = S.comp_items.map((it) => {
  if (it.status !== 'rewritten') return it;
  const h = hits[k++] || [];
  return h.length ? { ...it, status: 'dropped', final: null, why: it.why.concat('rewrite failed the hard word list again: ' + h.join(', ')) } : it;
});
const notes = [];
const hooks = [];
for (const h of S.hooks) {
  const lines = {};
  for (const len of ['6', '15', '30']) {
    const it = items.find((i) => i.id === h.id + ':' + len);
    if (it.final) lines[len] = it.final; else notes.push(h.id + ' ' + len + ' s line dropped (' + it.why.join('; ') + ')');
  }
  const broll = ['A', 'B', 'C'].map((l) => { const it = items.find((i) => i.id === h.id + ':' + l); if (!it.final) notes.push(h.id + ' b-roll ' + l + ' dropped (' + it.why.join('; ') + ')'); return it.final; });
  if (!Object.keys(lines).length) { notes.push(h.id + ' dropped: no line left'); continue; }
  hooks.push({ id: h.id, lines, broll });
}
for (const it of items) if (it.status === 'rewritten') notes.push(it.id + ' rewritten: "' + it.text + '" -> "' + it.final + '"');
if (!hooks.length) throw new Error('compliance: no hook has a line left after the checks');
const { body, ...rest } = S;
const compliance = { items: items.map(({ id, kind, status, text, final, why }) => ({ id, kind, status, text, final, why })), notes };
return [{ json: { ...rest, hooks, compliance } }];

// The brief's Look overrides the written one, but it goes through the hard word list too.
const S = $input.first().json;
return [{ json: { ...S, body: { texts: [S.brief.look] } } }];

// A hit: ignore the brief's line, use the vision path, and keep a note in the run data.
const S = $('Look: brief prep').first().json;
const hits = ($input.first().json.hits || [[]])[0];
const { body, ...rest } = S;
return [{ json: { ...rest, look_brief_ok: hits.length === 0, ...(hits.length ? { look_brief_rejected: { line: S.brief.look, hits } } : {}) } }];

// The middles of S1, S3 and S5 (spec 4.3, matching part 1).
const S = $input.first().json;
const by = Object.fromEntries(S.beats.map((b) => [b.name, b]));
const at = ['S1', 'S3', 'S5'].map((n) => Math.round(((by[n].start + by[n].end) / 2) * 100) / 100);
return [{ json: { ...S, look_at: at, body: { file: S.source, at } } }];

const MODEL = 'google/gemini-4-argon';
const llmText = (r) => { const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : ''; return Array.isArray(c) ? c.map((p) => (p && p.text) || '').join('') : String(c == null ? '' : c); };
const parseJson = (s) => JSON.parse(String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
const cost = (r) => Number((r && r.usage && r.usage.cost) || 0);
const strip = (o) => { const { body, ...rest } = o; return rest; };

const S = $('Look: frames prep').first().json;
const files = $('Look: files').all().map((i) => i.json.rel);
const items = $input.all();
const parts = [{ type: 'text', text: 'Describe only the look of these frames in one line of at most 30 words for a cinematographer: light sources and their colour, time of day, palette, contrast, lens and depth of field, grain. Do not mention people, bodies, objects\' brands or text. Answer with the line only.' }];
