const HOOKS = ['H1', 'H2'], LENGTHS = [6, 15, 30], FORMATS = ['9X16', '1X1', '16X9'];
const all = [];
for (const h of HOOKS) for (const l of LENGTHS) for (const f of FORMATS) all.push(h + '_' + l + 'S_' + f);
const passed = R.results.filter((r) => r.status === 'passed');
const failed = R.results.filter((r) => r.status === 'failed');
const first = (r) => r.version + ': ' + clip(r.qa.reasons[0], 90);
let summary = all.length + ' versions: ' + passed.length + ' passed, ' + failed.length + ' failed';
if (failed.length) summary += ' (' + failed.slice(0, 5).map(first).join('; ') + (failed.length > 5 ? '; …' : '') + ')';
if (R.not_made.length) summary += ', ' + R.not_made.length + ' not made';
const rows = all.map((v) => {
  const r = byId[v];
  if (!r) return '<tr><td>' + esc(v) + '</td><td>not made</td><td>' + esc(notMadeById[v] ? notMadeById[v].reason : '') + '</td></tr>';
  return '<tr><td>' + esc(v) + '</td><td>' + (r.status === 'passed' ? 'passed' : '<b>FAILED</b>') + '</td><td>' + (r.qa.reasons.length ? r.qa.reasons.map(esc).join('<br>') : '') + '</td></tr>';
}).join('');
// the sheet is served by the "Sheet link" webhook of this workflow; the random token in the URL is what protects it
const sheet_url = sheet.file ? $execution.resumeFormUrl.match(/^https?:\/\/[^\/]+/)[0] + '/webhook/ad-versions-sheet?run=' + encodeURIComponent(S.run_id) + '&token=' + R.sheet_token : null;
const html = '<p><b>' + esc(summary) + '</b></p>'
  + (sheet_url ? '<p><a href="' + sheet_url + '" target="_blank">Contact sheet, full size</a> (green PASS, red FAIL)</p><p><img src="' + sheet_url + '" width="900" alt="contact sheet"></p>'
    : '<p>Contact sheet: not made (' + esc(sheet.error) + ')</p>')
  + '<p>Tick the versions to put in the package (the ones that passed are ticked). To reject a version, leave it unticked and say why in the notes box, one note per line: <code>H2_6S_1X1: voice clipped</code>. '
  + '<b>A version that failed QA can still go in:</b> tick it and write <code>VERSION: why</code> in the notes box; without that note it is rejected. Other lines in the box are a general note.</p>'
  + '<table><thead><tr><th>Version</th><th>QA</th><th>Reasons</th></tr></thead><tbody>' + rows + '</tbody></table>';
return [{ json: { summary, sheet, sheet_url, sheet_token: R.sheet_token, all, passed: passed.map((r) => r.version), default_checked: passed.map((r) => r.version).join(','), html,
  form_url: $execution.resumeFormUrl, waiting_since: new Date().toISOString(),
  results: R.results, not_made: R.not_made, llm_usd_12b: R.results.reduce((a, r) => a + (r.llm_usd || 0), 0) } }];

// run.json now holds the QA results and the approval form's URL (the controller opens it).
const { saved_at, ...S } = $('Run data: build run.json').first().json;
const A = $input.first().json;
const data = { ...S, qa: A.results, not_made: A.not_made, summary: A.summary, sheet: A.sheet.file,
  llm_usd: S.llm_usd + A.llm_usd_12b,
  sheet_token: A.sheet_token, sheet_url: A.sheet_url,
  approval: { status: 'waiting', form_url: A.form_url, waiting_since: A.waiting_since, wait_limit: '7 days' }, saved_at: new Date().toISOString() };
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(data, null, 1)), 'run.json', 'application/json');
return [{ json: { form_url: A.form_url, run: data }, binary: { data: bin } }];

// What the reviewer ticked and wrote. No submission time = the wait ran out (expired): nothing is packaged.
const r = $input.first().json;
const A = $('Approval: build').first().json;
if (!r.submittedAt) return [{ json: { expired: true, channel: 'form', approver: 'reviewer (form)', approved: [], rejected: [], ignored: [], refused: [], approved_notes: {}, general_note: '', submitted_at: null } }];
const sel = r['Approve versions'];
const ticked = (Array.isArray(sel) ? sel : (sel ? [sel] : [])).map((x) => String(x).trim());
const byId = Object.fromEntries(A.results.map((x) => [x.version, x]));
const notes = {}; const general = [];
for (const line of String(r['Review notes'] || '').split(/\r?\n/)) {
  const t = line.trim(); if (!t) continue;
  const m = t.match(/^(H\d_\d+S_[A-Z0-9]+)\s*[:\-–]\s*(.+)$/);
  if (m) notes[m[1]] = (notes[m[1]] ? notes[m[1]] + ' ' : '') + m[2]; else general.push(t);
}
const approved = [], rejected = [], ignored = [], refused = [], approved_notes = {};
for (const v of A.all) {
  const res = byId[v];
  const made = res && res.file;
  if (ticked.includes(v) && made) {
    if (res.status === 'failed' && !notes[v]) {        // approving over a QA failure needs a reason on record
      refused.push(v);
      rejected.push({ version: v, note: 'override needs a note: failed QA (' + res.qa.reasons.join('; ') + '); tick it again and write "' + v + ': why" in the notes box' });
      continue;
    }
    approved.push(v); approved_notes[v] = notes[v] || ''; continue;
  }
  if (ticked.includes(v) && !made) ignored.push(v);
  const nm = A.not_made.find((n) => n.version === v);
  const why = nm ? 'not made: ' + nm.reason : (!res ? 'not made' : res.status === 'failed' ? 'failed QA: ' + res.qa.reasons.join('; ') : 'not approved by the reviewer');
  rejected.push({ version: v, note: notes[v] ? notes[v] + ' (' + why + ')' : why });
}
return [{ json: { expired: false, channel: 'form', approver: 'reviewer (form)', approved, rejected, ignored, refused, approved_notes, general_note: general.join(' '), submitted_at: r.submittedAt } }];

// POST /package body per docs/api.md. Costs: GPU and voice are not costed yet (0); upload only for a live b-roll run (R2 env needed).
const P = $input.first().json;
if (P.expired) return [{ json: { ...P, any: false } }];
const A = $('Approval: build').first().json;
const S = $('Run: state for 12b').first().json;
const byId = Object.fromEntries(A.results.map((x) => [x.version, x]));
const hookOf = (id) => (S.hooks || []).find((h) => h.id === id);
const approved = P.approved.map((v) => {
  const r = byId[v];
  const hook = hookOf(r.hook);
  return { version: v, file: r.file, hook_text: (hook && hook.lines && hook.lines['6']) || r.line, script: r.line, length_s: r.length_s, fmt: r.fmt,
    synthetic_media: true, qa: r.qa, note: P.approved_notes[v] || '', v: 1, approver: P.approver || 'reviewer (form)', approved_at: P.submitted_at };
});
const campaign = String(S.brief.product || '').trim().slice(0, 60) || 'Campaign';
const mode = (S.voice_mode === 'real' ? 'real' : 'stand-in') + ' voice, ' + (S.broll_mode === 'live' ? 'live' : 'stand-in') + ' b-roll; GPU and voice not costed yet';
const run = {
  brand: String(S.rulebook.brand || S.brief.brand).slice(0, 40), campaign,
  started_at: $('Brief form').first().json.submittedAt, review_ready_at: A.waiting_since, finished_at: new Date().toISOString(),
  disclaimer: S.disclaimer, mode,
  gpu_minutes: 0, gpu_rate_usd_h: 0, voice_usd: 0,
  llm_usd: Math.round((S.llm_usd + A.llm_usd_12b) * 1e6) / 1e6,
};
if (P.general_note) run.review_note = P.general_note;
if (S.brief.landing_url) run.link = S.brief.landing_url;
if (S.brief.cta) run.cta = S.brief.cta;
const upload = S.broll_mode === 'live';                  // a stand-in run has no R2 environment to upload to; a live one needs it, or /package says so
return [{ json: { ...P, any: approved.length > 0, body: { run_id: S.run_id, run, approved, rejected: P.rejected, upload } } }];

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// What went wrong in an HTTP answer (full response with neverError, or a node error item)
const httpFail = (r) => {
  if (r.error) return clip(typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)), 300);
  const b = r.body;
  if (b && typeof b === 'object') {
    if (typeof b.error === 'string') return clip(b.error, 300);
    if (typeof b.detail === 'string') return clip(b.detail, 300);
    if (Array.isArray(b.detail)) return clip(b.detail.map((d) => (d.loc ? d.loc.join('.') + ': ' : '') + (d.msg || '')).join('; '), 300);
  }
  return 'HTTP ' + r.statusCode;
};
const httpOk = (r) => !r.error && r.statusCode >= 200 && r.statusCode < 300 && r.body && typeof r.body === 'object';
const B = $('Package: body').first().json;
const r = $input.first().json;
const ok = httpOk(r) && r.body.folder;
return [{ json: { ...B, package_status: ok ? 'built' : 'failed',
  package: ok ? { ok: true, folder: r.body.folder, files: r.body.files, report: r.body.report, link: r.body.link || null } : { ok: false, error: httpFail(r) } } }];

const B = $input.first().json;
const status = B.expired ? 'expired' : 'nothing_approved';
return [{ json: { ...B, package_status: status, package: { ok: false, error: B.expired ? 'the ' + (B.channel || 'form') + ' approval got no answer in 7 days: expired, nothing packaged' : 'nothing was approved: no package' + (B.channel === 'Telegram' ? ' (no version passed QA)' : '') } } }];

// run.json for good: the package folder and the report numbers, who approved what (or that the approval expired).
const { saved_at, ...S } = $('Run data: build run.json').first().json;
const A = $('Approval: build').first().json;
const B = $input.first().json;
let tgErr = null;                       // set when Telegram failed before the approval (the form took over)
try { tgErr = $('Telegram: failed').first().json.telegram_error || null; } catch (e) { tgErr = null; }
const data = { ...S, qa: A.results, not_made: A.not_made, summary: A.summary, sheet: A.sheet.file,
  sheet_token: A.sheet_token, sheet_url: A.sheet_url,
  llm_usd: Math.round((S.llm_usd + A.llm_usd_12b) * 1e6) / 1e6,
  approval: { status: B.expired ? 'expired' : 'done', via: B.approver || null, channel: B.channel || null, form_url: A.form_url, submitted_at: B.submitted_at, approved: B.approved, approved_notes: B.approved_notes,
    rejected: B.rejected, ignored: B.ignored, override_refused: B.refused, note: B.general_note },
  telegram_error: tgErr, telegram_done: B.telegram_done || null,
  package_status: B.package_status, package: B.package, saved_at: new Date().toISOString() };
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(data, null, 1)), 'run.json', 'application/json');
return [{ json: { run_id: S.run_id, summary: A.summary, package_status: B.package_status, package: B.package, approved: B.approved.length, rejected: B.rejected.length }, binary: { data: bin } }];

// The public sheet link: ?run=<digits>&token=<32 hex>. Anything else never reaches the file system.
const q = $input.first().json.query || {};
const run = String(q.run || ''), token = String(q.token || '');
const ok = /^[0-9]{1,12}$/.test(run) && /^[0-9a-f]{32}$/.test(token);
return [{ json: { ok, run, token, path: ok ? '/data/runs/' + run + '/run.json' : '/data/none' } }];

// Compare the token with the one in run.json (the whole string, no early exit); the sheet itself is always runs/<run>/sheet.jpg.
const c = $('Sheet link: check').first().json;
let ok = false;
if (c.ok) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
    const want = String(JSON.parse(buf.toString('utf8')).sheet_token || '');
    let diff = want.length === c.token.length && want.length === 32 ? 0 : 1;
    for (let i = 0; i < 32; i++) diff |= (want.charCodeAt(i) || 0) ^ (c.token.charCodeAt(i) || 0);
    ok = diff === 0;
  } catch (e) { ok = false; }
}
return { json: { ok, path: ok ? '/data/runs/' + c.run + '/sheet.jpg' : '/data/none' } };

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// The chat id is the one thing kept outside the repo and outside n8n's credential: data/config/telegram.json, {"telegram_chat_id": "<digits>"}.
const chatIdFrom = async (ctx, input) => {
  if (!input || !input.binary || !input.binary.data) throw new Error('config/telegram.json was not read');
  let cfg;
  try { cfg = JSON.parse((await ctx.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); } catch (e) { throw new Error('config/telegram.json is not valid JSON'); }
  const id = String(cfg && cfg.telegram_chat_id != null ? cfg.telegram_chat_id : '').trim();
  if (!/^-?\d{1,20}$/.test(id)) throw new Error('config/telegram.json: telegram_chat_id must be digits');
  return id;
};

const A = $('Approval: build').first().json;
const RUN = String($execution.id);
const chat_id = await chatIdFrom(this, $input.first());
const passed = A.results.filter((r) => r.status === 'passed');
const failed = A.results.filter((r) => r.status === 'failed');
// The photo's caption: the summary line, with as many failures as fit (Telegram allows 1024 characters), then "+N more".
// Cut to length first and escape last, so a cut never splits an entity.
let head = A.all.length + ' versions: ' + passed.length + ' passed, ' + failed.length + ' failed';
if (A.not_made.length) head += ', ' + A.not_made.length + ' not made';
const fl = failed.map((r) => r.version + ': ' + clip((r.qa.reasons || [])[0] || 'QA failed', 90));
let shown = [];
const build = (list) => head + (fl.length ? ' (' + list.join('; ') + (fl.length > list.length ? (list.length ? '; ' : '') + '+' + (fl.length - list.length) + ' more' : '') + ')' : '');
for (const f of fl) { if (build([...shown, f]).length > 800) break; shown = [...shown, f]; }
const caption = esc(clip(build(shown), 1000));
const ask = 'Run ' + RUN + ': ' + passed.length + ' of ' + A.all.length + ' versions passed QA. '
  + (passed.length ? 'Approve passed puts the ' + passed.length + ' that passed in the package and rejects the rest. ' : 'Approve passed has nothing to approve (no version passed QA). ')
  + 'Review opens the form, to tick versions and add notes.';
const review_text = 'Review run ' + RUN + ': tick the versions to approve, add notes, submit.\n<a href="' + esc(A.form_url) + '">Open the review form</a>';
return [{ json: { chat_id, caption, ask, review_text } }];

// Approve passed, pressed on Telegram: every version that passed is approved, every other one is rejected. No answer within the wait limit = expired.
const r = $input.first().json;
const A = $('Approval: build').first().json;
const approver = 'reviewer (Telegram)', channel = 'Telegram';
if (!r.data || r.data.approved !== true) return [{ json: { expired: true, channel, approver, approved: [], rejected: [], ignored: [], refused: [], approved_notes: {}, general_note: '', submitted_at: null } }];
const byId = Object.fromEntries(A.results.map((x) => [x.version, x]));
const approved = [], rejected = [], approved_notes = {};
for (const v of A.all) {
  const res = byId[v];
  if (res && res.file && res.status === 'passed') { approved.push(v); approved_notes[v] = ''; continue; }
  const nm = A.not_made.find((n) => n.version === v);
  const why = nm ? 'not made: ' + nm.reason : !res ? 'not made' : res.file ? 'not approved (failed QA: ' + res.qa.reasons.join('; ') + ')' : 'failed: ' + res.qa.reasons.join('; ');
  rejected.push({ version: v, note: why });
}
const general_note = approved.length ? 'approved on Telegram' : 'nothing approved (no version passed QA)';
return [{ json: { expired: false, channel, approver, approved, rejected, ignored: [], refused: [], approved_notes, general_note, submitted_at: new Date().toISOString() } }];

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// never let a bot token reach run.json or a message, whatever the API echoes back
const scrub = (s) => String(s == null ? '' : s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, '***');
const errText = (e) => scrub(typeof e === 'string' ? e : (e && (e.description || e.message)) || 'unknown error');
// Telegram did not work (credential, network, chat not started, missing sheet or config): say so in run.json and go on with the form.
const e = $input.first().json;
return [{ json: { telegram_error: clip(e.error != null ? errText(e.error) : 'Telegram step failed (no error text)', 300) } }];

// run.json again, now with telegram_error (the form is the way to approve).
const P = $('Run: run.json (awaiting approval)').first().json;
const data = { ...P.run, telegram_error: $input.first().json.telegram_error, saved_at: new Date().toISOString() };
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(data, null, 1)), 'run.json', 'application/json');
return [{ json: { telegram_error: data.telegram_error, form_url: P.form_url }, binary: { data: bin } }];

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// never let a bot token reach run.json or a message, whatever the API echoes back
const scrub = (s) => String(s == null ? '' : s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, '***');
const errText = (e) => scrub(typeof e === 'string' ? e : (e && (e.description || e.message)) || 'unknown error');
// The chat id is the one thing kept outside the repo and outside n8n's credential: data/config/telegram.json, {"telegram_chat_id": "<digits>"}.
const chatIdFrom = async (ctx, input) => {
  if (!input || !input.binary || !input.binary.data) throw new Error('config/telegram.json was not read');
  let cfg;
  try { cfg = JSON.parse((await ctx.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); } catch (e) { throw new Error('config/telegram.json is not valid JSON'); }
  const id = String(cfg && cfg.telegram_chat_id != null ? cfg.telegram_chat_id : '').trim();
  if (!/^-?\d{1,20}$/.test(id)) throw new Error('config/telegram.json: telegram_chat_id must be digits');
  return id;
};

// The done message, or the "nothing packaged" one: run, counts, cost per asset, turnaround, package folder. Never throws.
try {
  const chat_id = await chatIdFrom(this, $input.first());
  const B = $('Telegram: send done?').first().json;
  const run = String($('Run: state for 12b').first().json.run_id);
  const usd = (x) => (x == null ? 'n/a' : x >= 0.01 ? '$' + x.toFixed(2) : x >= 0.001 ? '$' + x.toFixed(3) : x > 0 ? '< $0.001' : '$0.00');
  const min = (x) => (x == null ? 'n/a' : Math.round(x * 10) / 10 + ' min');
  let lines;
  if (B.package_status === 'built') {
    const rep = (B.package && B.package.report) || {};
    lines = ['Run ' + run + ' is packaged.',
      'Approved ' + B.approved.length + ', rejected ' + B.rejected.length + ' (' + ((B.body.approved[0] && B.body.approved[0].approver) || 'no approver') + ').',
      'Cost per asset: ' + usd(rep.cost_per_asset_usd) + (B.body.run.mode ? ' (' + B.body.run.mode + ')' : ''),
      'Turnaround: machine time to review-ready ' + min(rep.machine_min) + ', total ' + min(rep.turnaround_min) + '.',
      'Package: ' + B.package.folder];
    if (B.package.link) lines.push('Link: ' + B.package.link);
  } else if (B.package_status === 'expired') {
    lines = ['Run ' + run + ': the ' + (B.channel || 'form') + ' approval got no answer in 7 days. Expired, nothing packaged.'];
  } else {
    lines = ['Run ' + run + ': nothing approved' + (B.channel === 'Telegram' ? ' (no version passed QA)' : '') + ', no package.', 'Rejected ' + B.rejected.length + '.'];
  }
  return [{ json: { chat_id, text: esc(lines.join('\n')) } }];
} catch (e) {
  return [{ json: { error: clip(errText(e), 300) } }];
}

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// never let a bot token reach run.json or a message, whatever the API echoes back
const scrub = (s) => String(s == null ? '' : s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, '***');
const errText = (e) => scrub(typeof e === 'string' ? e : (e && (e.description || e.message)) || 'unknown error');
// Back to the package answer, plus what Telegram did with the message (skipped = no chat id could be read).
const B = $('Telegram: send done?').first().json;
const T = $('Telegram: done text').first().json;
const r = $input.first().json;
const why = (e) => (/^config\/telegram\.json/.test(e) ? 'no chat id' : clip(e, 200));       // chatIdFrom's own messages are the no-chat-id case; any other text-step failure keeps its reason
const telegram_done = T.error ? 'skipped: ' + why(T.error) : r.error ? 'failed: ' + clip(errText(r.error), 300) : 'sent';
return [{ json: { ...B, telegram_done } }];
